'use strict';

// Generated by Clause Sonnet 5.5 / Refactored by HellXCore
//
// Window tracking for KDE Plasma 6 on Wayland, the Electron half (src/main/kwin-bridge.js).
//
// x11-watch.js stays off in a Wayland session: the X server only sees XWayland windows. KWin sees
// them all, so a small KWin script (kwin-windows.qml) runs inside it and pushes what it knows
// over D-Bus to the service started here. What arrives is already in the shapes x11.js parses
// xprop/xwininfo output into, so x11.buildSnapshot() does the rest and windows.js gets the same
// snapshot as from startX11Watch.
//
//   KWin script --Update(json)--> org.capri.WindowBridge (here) --> x11.buildSnapshot --> onSnapshot
//                 <--reply: { selfPid, selfTitle } (so the script leaves the overlay out)
//   KWin script --Cursor("x,y")-> where the pointer really is (XWayland only follows it over X windows)
//   KWin script --Command(json)-> a key it was given (Ctrl+Alt+C: { name: 'toggle' })
//   KWin script --Poll()-------> { self, commands }: who she is, and what waits for the script:
//                                [{ op: 'close', pids }] closing an app, [{ op: 'focus', on }] the keyboard for her
//
// What only the Windows helper told her, now from here: `ai` (the AIs the window in front is, by the
// script), `game` (the library folder of the game in front, from its process: games.js), `usb` and
// `plug` (the removable drives and the last device plugged in or out: devices.js).
//
// The same watcher also answers what apps are open (apps-linux.js, through current()) and where the
// pointer is (windows.js).
//
// No npm dependency: the D-Bus side is dbus-mini.js. The script is written to scriptDir (a real
// path: KWin cannot read inside an asar) and loaded/unloaded through org.kde.KWin /Scripting;
// nothing is installed into the user's KWin scripts. Only KWin's own connection may call Update.

const fs = require('node:fs');
const path = require('node:path');
const x11 = require('./x11');
const { Bus } = require('./dbus-mini');
const { createDevices } = require('./devices');
const { createGameWatcher } = require('./games');

const BUS_NAME = 'org.capri.WindowBridge';
const OBJECT_PATH = '/org/capri/WindowBridge';
const SCRIPT_NAME = 'capri-windows';
const FIRST_UPDATE_MS = 6000; // the script says nothing in this time: give up (onState(false))

const isNum = (n) => typeof n === 'number' && Number.isFinite(n);
const list = (v) => (Array.isArray(v) ? v : []);

const COMMANDS = new Set(['toggle']); // the keys the script may report
const isRect = (r) => r && typeof r === 'object' && [r.x, r.y, r.w, r.h].every(isNum) && r.w > 0 && r.h > 0;
const MAX_PIDS = 64;

let active = null; // the running watcher: what apps-linux.js asks (current())

// KWin's logical pixels -> the X screen's pixels. 'logical' (default): the same thing, which is
// right while XWayland is scaled by KWin (Plasma's default, "Legacy applications: scaled by the
// system"). 'physical': the user let XWayland apps scale themselves, so X pixels are real ones;
// each rectangle is multiplied by the scale of the output holding its centre.
function toXPixels(rect, outputs, units) {
  if (units !== 'physical') return rect;
  const cx = rect.x + rect.w / 2;
  const cy = rect.y + rect.h / 2;
  const out = list(outputs).find((o) => cx >= o.x && cx < o.x + o.w && cy >= o.y && cy < o.y + o.h);
  const s = (out && out.s) || 1;
  return { x: Math.round(rect.x * s), y: Math.round(rect.y * s), w: Math.round(rect.w * s), h: Math.round(rect.h * s) };
}

// What the KWin script sent -> the snapshot in the Windows helper's format. The message comes off
// the session bus, so its shape is checked rather than trusted.
function fromPayload(payload, { units = 'logical' } = {}) {
  if (!payload || typeof payload !== 'object' || payload.v !== 1) throw new Error('unknown payload');
  const r = payload.root || {};
  const root = {
    active: isNum(r.active) ? r.active : null,
    stacking: list(r.stacking).filter(isNum), // front first, as x11.parseRoot gives it
    desktop: isNum(r.desktop) ? r.desktop : null,
  };

  const infos = new Map();
  for (const [key, v] of Object.entries(payload.infos || {})) {
    const id = Number(key);
    if (!isNum(id) || !v || typeof v !== 'object') continue;
    infos.set(id, {
      types: list(v.types).filter((t) => typeof t === 'string'),
      state: list(v.state).filter((t) => typeof t === 'string'),
      desktop: isNum(v.desktop) ? v.desktop : null,
      frame: null,
      csd: null,
      pid: isNum(v.pid) ? v.pid : null,
    });
  }

  const rects = new Map();
  for (const [key, v] of Object.entries(payload.rects || {})) {
    const id = Number(key);
    if (!isNum(id) || !v || ![v.x, v.y, v.w, v.h].every(isNum)) continue;
    rects.set(id, toXPixels({ x: v.x, y: v.y, w: v.w, h: v.h }, payload.outputs, units));
  }

  const snap = x11.buildSnapshot({ root, infos, rects, self: {} });
  // what only the KWin side knows: the AIs the window in front is (keys only, no titles)
  snap.ai = list(payload.ai).filter((k) => typeof k === 'string').slice(0, 8);
  // where KWin has the overlay (its frame, KWin's pixels): a native Wayland client does not know
  const s = payload.self;
  snap.self = s && [s.x, s.y, s.w, s.h].every(isNum) ? { x: s.x, y: s.y, w: s.w, h: s.h } : null;
  // `game`, `usb`, `plug` stay as buildSnapshot leaves them (Windows reports those)
  return snap;
}

// The windows of an update, for the list of open apps: [{ id, pid, cls, app, types, state }].
// cls: the window class, app: its desktop file ("org.kde.konsole"). Never a title.
function windowsOf(payload) {
  const out = [];
  for (const [key, v] of Object.entries((payload && payload.infos) || {})) {
    const id = Number(key);
    if (!isNum(id) || !v || typeof v !== 'object') continue;
    out.push({
      id,
      pid: isNum(v.pid) ? v.pid : null,
      cls: typeof v.cls === 'string' ? v.cls : '',
      app: typeof v.app === 'string' ? v.app : '',
      types: list(v.types).filter((t) => typeof t === 'string'),
      state: list(v.state).filter((t) => typeof t === 'string'),
    });
  }
  return out;
}

// "123,456" -> { x: 123, y: 456 } (KWin's logical pixels), or null. With the overlay's place known
// the script adds the same point from the overlay's own top left corner: "123,456,23,56", then
// `rel` ({ x: 23, y: 56 }). Native Wayland's input region follows it (wayland-toggle.js).
function parseCursor(text) {
  const m = /^(-?\d{1,6}),(-?\d{1,6})(?:,(-?\d{1,6}),(-?\d{1,6}))?$/.exec(String(text));
  if (!m) return null;
  const at = { x: Number(m[1]), y: Number(m[2]) };
  if (m[3] !== undefined) at.rel = { x: Number(m[3]), y: Number(m[4]) };
  return at;
}

// "id,x,y,w,h" (KWin's logical pixels, whole numbers) -> { id, x, y, w, h }, or null. The light
// channel of a window being dragged or resized (kwin-windows.qml: Move).
function parseMove(text) {
  const m = /^(\d{1,12}),(-?\d{1,6}),(-?\d{1,6}),(\d{1,6}),(\d{1,6})$/.exec(String(text));
  if (!m) return null;
  const [id, x, y, w, h] = m.slice(1).map(Number);
  return w > 0 && h > 0 ? { id, x, y, w, h } : null;
}

// The snapshot with one window's rectangle replaced; null if there is nothing to change (the window
// is not in the last snapshot, or it did not move).
function applyMove(snap, mv, outputs, units) {
  const i = snap.wins.findIndex((w) => w.id === mv.id);
  if (i < 0) return null;
  const r = toXPixels({ x: mv.x, y: mv.y, w: mv.w, h: mv.h }, outputs, units);
  const old = snap.wins[i];
  if (old.x === r.x && old.y === r.y && old.w === r.w && old.h === r.h) return null;
  const wins = snap.wins.slice();
  wins[i] = { ...old, ...r, max: false }; // a window being dragged is not maximized
  return { ...snap, wins };
}

// session: capabilities.linuxSession(). getSelf(): { pid, title } of the overlay (its pid and the
// window title it was given), to leave it out. scriptDir: a writable real directory.
// Same contract as startX11Watch: onSnapshot(snap) physical-pixel snapshots, onState(ok).
function startKWinWatch({
  session, getSelf = () => ({}), scriptDir, onSnapshot, onState = () => {}, onCommand = () => {}, onPointer = () => {},
  // what reads /sys and /proc (the tests give their own): watchDevices(onChange) -> the watcher
  watchDevices = (onChange) => createDevices({ onChange }), gameOf = createGameWatcher(),
  units = process.env.CAPRI_KWIN_UNITS === 'physical' ? 'physical' : 'logical',
  log = console,
}) {
  const noop = { stop() {} };
  const kde = /KDE/i.test(process.env.XDG_CURRENT_DESKTOP || '');
  // 'xwayland': Capri itself runs through XWayland inside the Wayland session; 'wayland': natively
  if (!['wayland', 'xwayland'].includes(session) || !kde) {
    log.log(`[capri] kwin watch: off (needs a KDE Wayland session, this is ${kde ? 'KDE' : 'not KDE'} / ${session || 'no session'})`);
    onState(false);
    return noop;
  }

  let stopped = false;
  let bus = null;
  let running = false; // has an update arrived (and onState(true))
  let lastJson = '';
  let lastSnap = null; // the last update's snapshot, to send again when only a device changed
  let firstTimer = null;
  const watched = watchDevices(() => lastSnap && emit(lastSnap));
  let windows = [];    // the last update's windows (windowsOf)
  let outputs = [];    // and its outputs (their scales)
  let cursor = null;   // the pointer, KWin's logical pixels
  const queue = [];    // commands for the script, taken by its next Poll

  // The light channel (Move): while one window is dragged, only its rectangle arrives. Latest wins:
  // a Move that comes before the previous one went out replaces it (at most one per MOVE_MIN_MS).
  const MOVE_MIN_MS = 8;

  // The pace of the script's poll: fast while something is going on (the pointer moved lately, her
  // chat holds the keyboard, a command was just given), slow when nothing is. Said in each answer.
  const POLL_FAST_MS = 150;
  const POLL_SLOW_MS = 500;
  const POLL_HOT_MS = 3000;
  let hotUntil = 0;
  let focusOn = false;
  let lastSelfKey = ''; // what the script was last told about (Update or Poll): said again only if it changed
  const hot = () => { hotUntil = Date.now() + POLL_HOT_MS; };
  const pollMs = () => (focusOn || queue.length || Date.now() < hotUntil ? POLL_FAST_MS : POLL_SLOW_MS);
  let pendingMove = null;
  let moveTimer = null;
  let lastMoveAt = 0;
  const flushMove = () => {
    moveTimer = null;
    const mv = pendingMove;
    pendingMove = null;
    lastMoveAt = Date.now();
    if (!mv || !lastSnap) return;
    const next = applyMove(lastSnap, mv, outputs, units);
    if (!next) return;
    lastSnap = next; // so a device change in between does not bring the old place back
    emit(next);
  };
  const move = (text) => {
    const mv = parseMove(text);
    if (!mv) return;
    pendingMove = mv;
    if (moveTimer) return;
    moveTimer = setTimeout(flushMove, Math.max(0, MOVE_MIN_MS - (Date.now() - lastMoveAt)));
  };

  const fail = (why) => {
    if (stopped) return;
    log.error(`[capri] kwin watch: ${why}`);
    onState(false);
  };

  const update = (text) => {
    try {
      const payload = JSON.parse(text);
      const snap = fromPayload(payload, { units });
      // the game in front: only the name of its folder in a launcher's library is passed on
      const front = payload.front || {};
      snap.game = gameOf(isNum(front.pid) ? front.pid : 0, typeof front.cls === 'string' ? front.cls : '');
      lastSnap = snap;
      // a full snapshot always overrides a Move still waiting
      clearTimeout(moveTimer);
      moveTimer = null;
      pendingMove = null;
      windows = windowsOf(payload);
      outputs = list(payload.outputs);
      if (!running) {
        running = true;
        clearTimeout(firstTimer);
        log.log('[capri] kwin watch: ready');
        onState(true);
      }
      emit(snap);
    } catch (err) {
      log.error('[capri] kwin watch: bad update:', err?.message ?? err);
    }
    lastSelfKey = JSON.stringify(selfReply()); // the script has it now: the next Poll need not say it
    return lastSelfKey;
  };

  // the snapshot with the devices as they are now; only when something changed
  const emit = (snap) => {
    const full = { ...snap, ...watched.snapshot() };
    const json = JSON.stringify(full);
    if (json === lastJson) return;
    lastJson = json;
    onSnapshot(full);
  };

  // Who she is, so the script leaves the overlay out of the list and can look after it: its pid and
  // title, and where it should be (KWin's pixels; only when they are the X screen's: 'logical').
  const selfReply = () => {
    const self = getSelf() || {};
    const reply = { selfPid: self.pid || 0, selfTitle: self.title || '' };
    if (units !== 'physical' && isRect(self.rect)) reply.selfRect = self.rect;
    return reply;
  };

  const KWIN = { destination: 'org.kde.KWin', path: '/Scripting', iface: 'org.kde.kwin.Scripting' };

  const start = async () => {
    watched.start();
    lastSelfKey = '';
    bus = await Bus.connect();
    bus.onClose = (err) => {
      if (!stopped) fail(`lost the session bus (${err?.message ?? err})`);
    };

    // The script runs inside KWin and calls through KWin's own bus connection, so the caller
    // must be the owner of org.kde.KWin. Anything else on the bus is refused.
    let kwinOwner = await bus.getNameOwner('org.kde.KWin');
    // CAPRI_KWIN_ANY_SENDER=1 switches the check off (if a KWin build calls from another connection)
    const anySender = process.env.CAPRI_KWIN_ANY_SENDER === '1';
    let refused = false;
    const fromKWin = async (sender) => {
      if (anySender || sender === kwinOwner) return true;
      try {
        kwinOwner = await bus.getNameOwner('org.kde.KWin');
      } catch {
        // KWin is gone
      }
      if (sender === kwinOwner) return true;
      if (!refused) {
        refused = true; // said once
        log.error(`[capri] kwin watch: refused an Update from ${sender}, org.kde.KWin is ${kwinOwner} (CAPRI_KWIN_ANY_SENDER=1 lifts the check)`);
      }
      return false;
    };

    const guarded = (inSig, outSig, fn) => ({
      in: inSig,
      out: outSig,
      fn: async (args, { sender }) => {
        if (!(await fromKWin(sender))) {
          throw Object.assign(new Error('only KWin may call this'), { dbusName: 'org.freedesktop.DBus.Error.AccessDenied' });
        }
        return fn(args);
      },
    });
    bus.export(OBJECT_PATH, BUS_NAME, {
      Update: guarded('s', 's', ([text]) => [update(text)]),
      Move: guarded('s', '', ([text]) => {
        move(text);
        return [];
      }),
      Cursor: guarded('s', '', ([text]) => {
        const next = parseCursor(text);
        if (next) {
          cursor = next;
          hot();
          if (next.rel) onPointer(next.rel); // from the overlay's top left corner, in KWin's pixels
        }
        return [];
      }),
      Command: guarded('s', '', ([text]) => {
        try {
          const { name } = JSON.parse(text);
          if (COMMANDS.has(name)) onCommand(name);
        } catch {
          // not a command of ours
        }
        return [];
      }),
      Poll: guarded('', 's', () => {
        const reply = { next: pollMs() };
        const self = JSON.stringify(selfReply());
        if (self !== lastSelfKey) { // only when it changed since the script last heard it
          lastSelfKey = self;
          reply.self = JSON.parse(self);
        }
        reply.commands = queue.splice(0);
        return [JSON.stringify(reply)];
      }),
    });
    const owned = await bus.requestName(BUS_NAME, 4); // 4: DO_NOT_QUEUE
    if (owned !== 1) throw new Error(`${BUS_NAME} is taken (another Capri running?)`);

    // the script, written out where KWin can read it, and started
    fs.mkdirSync(scriptDir, { recursive: true });
    const file = path.join(scriptDir, `${SCRIPT_NAME}.qml`);
    fs.writeFileSync(file, fs.readFileSync(path.join(__dirname, 'kwin-windows.qml')));

    const [loaded] = await bus.call({ ...KWIN, member: 'isScriptLoaded', args: [['s', SCRIPT_NAME]] });
    if (loaded) await bus.call({ ...KWIN, member: 'unloadScript', args: [['s', SCRIPT_NAME]] }); // a leftover
    const [id] = await bus.call({ ...KWIN, member: 'loadDeclarativeScript', args: [['s', file], ['s', SCRIPT_NAME]] });
    if (id < 0) throw new Error('KWin did not load the script');
    await bus.call({ destination: 'org.kde.KWin', path: `/Scripting/Script${id}`, iface: 'org.kde.kwin.Script', member: 'run' });

    if (stopped) return;
    firstTimer = setTimeout(() => {
      if (!running) fail('the KWin script sent nothing (see: journalctl --user -b | grep -i capri-windows)');
    }, FIRST_UPDATE_MS);
  };

  start().catch((err) => fail(err?.message ?? String(err)));

  const api = {
    get ready() {
      return running && !stopped;
    },
    // the windows with a window open, for the list of apps: [{ id, pid, cls, app, types, state }]
    windows: () => windows.slice(),
    // where the pointer is, in the X screen's pixels ({ x, y }), or null until KWin has said
    cursor() {
      if (!cursor) return null;
      const p = toXPixels({ x: cursor.x, y: cursor.y, w: 0, h: 0 }, outputs, units);
      return { x: p.x, y: p.y };
    },
    // asks KWin to close the windows of these processes, as their close button would
    closeApps(pids) {
      const ids = [...new Set(list(pids).filter((n) => Number.isInteger(n) && n > 1))].slice(0, MAX_PIDS);
      if (ids.length) {
        queue.push({ op: 'close', pids: ids });
        hot();
      }
    },
    // the keyboard for her overlay (her chat is open) or back to the window you were on: KWin does
    // not give it to a window that asked for it itself, so the script activates her
    focus(on) {
      focusOn = Boolean(on);
      queue.push({ op: 'focus', on: focusOn });
      hot();
    },
    stop() {
      stopped = true;
      clearTimeout(firstTimer);
      clearTimeout(moveTimer);
      watched.stop();
      if (active === api) active = null;
      if (!bus) return;
      bus.call({ ...KWIN, member: 'unloadScript', args: [['s', SCRIPT_NAME]] }).catch(() => {}).finally(() => bus.close());
    },
  };
  active = api;
  return api;
}

// the running watcher, or null (apps-linux.js, windows.js)
const current = () => (active && active.ready ? active : null);

module.exports = { startKWinWatch, current, fromPayload, windowsOf, parseCursor, parseMove, applyMove, toXPixels, BUS_NAME, OBJECT_PATH, SCRIPT_NAME };
